class Solution {
public:
    int countKConstraintSubstrings(string s, int k) {
        int n = s.size();
        int ans = 0;
        int left = 0;
        int zeros = 0, ones = 0;
        for (int right = 0; right < n; ++right) {
            if (s[right] == '0') zeros++;
            else ones++;
            while (zeros > k && ones > k) {
                if (s[left] == '0') zeros--;
                else ones--;
                left++;
            }
            ans += right - left + 1;
        }
        return ans;
    }
};

class Solution {
    public int countKConstraintSubstrings(String s, int k) {
        int n = s.length();
        int ans = 0;
        int left = 0;
        int zeros = 0, ones = 0;
        for (int right = 0; right < n; ++right) {
            if (s.charAt(right) == '0') zeros++;
            else ones++;
            while (zeros > k && ones > k) {
                if (s.charAt(left) == '0') zeros--;
                else ones--;
                left++;
            }
            ans += right - left + 1;
        }
        return ans;
    }
}

var countKConstraintSubstrings = function(s, k) {
    const n = s.length;
    let ans = 0;
    let left = 0;
    let zeros = 0, ones = 0;
    for (let right = 0; right < n; right++) {
        if (s[right] === '0') zeros++;
        else ones++;
        while (zeros > k && ones > k) {
            if (s[left] === '0') zeros--;
            else ones--;
            left++;
        }
        ans += right - left + 1;
    }
    return ans;
};
